// Decide what to ask Graph. Give an account key, a path, or a folder id (see the Input node).
//   path (or the account's onedrive_folder)  -> look the folder up, answer: its id
//   folder_id (+ drive_id if not your own)    -> check the id is alive, answer: where it is now
const input = $input.first().json;
const clean = (p) => String(p || '').trim().replace(/^\/+|\/+$/g, '');
let path = clean(input.path);
let account = String(input.account || '').trim();
if (account && !path && !input.folder_id) {
  const accounts = await this.helpers.httpRequest({ method: 'GET', url: 'http://pdf-decrypt:8080/accounts', json: true });
  if (!accounts[account]) throw new Error(`Unknown account '${account}'. Keys: ${Object.keys(accounts).join(', ')}`);
  path = clean(accounts[account].onedrive_folder);
}
const folderId = String(input.folder_id || '').trim();
const driveId = String(input.drive_id || '').trim();
if (!folderId && !path) throw new Error('Set account, path or folder_id in the Input node.');
const drive = driveId ? `drives/${encodeURIComponent(driveId)}` : 'me/drive';
const url = folderId
  ? `https://graph.microsoft.com/v1.0/${drive}/items/${encodeURIComponent(folderId)}`
  : `https://graph.microsoft.com/v1.0/me/drive/root:/${path.split('/').map(encodeURIComponent).join('/')}`;
return [{ json: { url, mode: folderId ? 'check id' : 'find id', account, path, folderId, driveId } }];

// Turn Graph's answer into something readable (and a config snippet to paste).
const ctx = $('Plan').first().json;
const r = $input.first().json;
if (r.error) {
  const status = r.error.httpCode || (String(r.error.message).match(/\b([45]\d{2})\b/) || [])[1] || (/not\s+be\s+found|not found/i.test(r.error.message) ? '404' : '?');
  const what = ctx.mode === 'check id' ? `folder id ${ctx.folderId}` : `path "${ctx.path}"`;
  return [{ json: {
    result: status === '404' || status === '410' ? `NOT FOUND: ${what} does not exist` : `ERROR ${status} for ${what}`,
    detail: r.error.message,
    hint: ctx.mode === 'check id'
      ? 'The id is dead (folder deleted, or moved to another drive). Find the folder by path instead.'
      : 'Check the spelling and capitalisation of the path, relative to the OneDrive root.',
  } }];
}
// A shortcut to someone else's folder: the folder that matters is the remote one.
const remote = r.remoteItem || null;
const target = remote || r;
const ref = (remote ? remote.parentReference : r.parentReference) || {};
const parent = String(ref.path || '').replace(/^.*root:/, '').replace(/^\/+|\/+$/g, '');
const currentPath = remote ? `(shortcut) ${r.name}` : [parent, r.name].filter(Boolean).join('/');
const snippet = ctx.driveId || remote ? { folder_id: target.id, drive_id: ref.driveId } : { folder_id: target.id };
return [{ json: {
  result: target.folder ? 'FOUND' : 'FOUND, BUT IT IS A FILE, NOT A FOLDER',
  name: r.name,
  current_path: currentPath,
  shortcut: remote ? 'yes: this path is a shortcut, the ids below are of the real folder in the other drive' : 'no',
  folder_id: target.id,
  drive_id: ref.driveId || '',
  for_private_config: `"statements": ${JSON.stringify(snippet)}  (add next to onedrive_folder; drive_id only for someone else's drive)`,
} }];
